import React, { useMemo, useState } from "react";

import { workers } from "../data/mockData";
import WorkerDetails from "./WorkerDetails";


function Workers() {

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");


  /*
   * Filter workers dynamically.
   *
   * This works regardless of whether the test configuration
   * contains 20, 50, 100, or more workers.
   */

  const filteredWorkers = useMemo(() => {

    return workers.filter((worker) => {

      const matchesSearch =
        worker.name
          .toLowerCase()
          .includes(search.toLowerCase()) ||
        worker.id
          .toLowerCase()
          .includes(search.toLowerCase());


      const matchesStatus =
        statusFilter === "all" ||
        worker.status === statusFilter;


      return matchesSearch && matchesStatus;
    });

  }, [search, statusFilter]);


  const healthyCount = workers.filter(
    (worker) => worker.status === "healthy"
  ).length;


  const failedCount = workers.filter(
    (worker) => worker.status === "failed"
  ).length;


  return (
    <div className="workers-page">

      {/* ----------------------------------------------------
          Page header
      ---------------------------------------------------- */}

      <div className="workers-page-header">

        <div>
          <h1>Workers</h1>

          <p>
            Monitor the health and performance of StreamForge
            processing workers
          </p>
        </div>

        <div className="worker-summary">

          <div className="summary-item">
            <span className="summary-dot healthy"></span>
            {healthyCount} Healthy
          </div>

          {failedCount > 0 && (
            <div className="summary-item">
              <span className="summary-dot failed"></span>
              {failedCount} Failed
            </div>
          )}

        </div>

      </div>


      {/* ----------------------------------------------------
          Filters
      ---------------------------------------------------- */}

      <div className="workers-toolbar">

        <div className="worker-search">

          <span className="search-icon">
            ⌕
          </span>

          <input
            type="text"
            placeholder="Search workers..."
            value={search}
            onChange={(event) =>
              setSearch(event.target.value)
            }
          />

        </div>


        <div className="worker-filters">

          <button
            className={
              statusFilter === "all"
                ? "filter-button active"
                : "filter-button"
            }
            onClick={() => setStatusFilter("all")}
          >
            All
          </button>

          <button
            className={
              statusFilter === "healthy"
                ? "filter-button active"
                : "filter-button"
            }
            onClick={() => setStatusFilter("healthy")}
          >
            Healthy
          </button>

          <button
            className={
              statusFilter === "failed"
                ? "filter-button active"
                : "filter-button"
            }
            onClick={() => setStatusFilter("failed")}
          >
            Failed
          </button>

        </div>

      </div>


      {/* ----------------------------------------------------
          Worker grid
      ---------------------------------------------------- */}

      <div className="workers-grid">

        {filteredWorkers.map((worker) => (

          <div
            className={`worker-card ${worker.status}`}
            key={worker.id}
          >

            {/* Card header */}

            <div className="worker-card-header">

              <div className="worker-name">

                <span
                  className={`worker-status-dot ${worker.status}`}
                ></span>

                <span>
                  {worker.name}
                </span>

              </div>

              <span className="worker-id">
                {worker.id}
              </span>

            </div>


            {/* Status */}

            <div className="worker-status-label">

              {worker.status === "healthy"
                ? "Healthy"
                : "Failed"}

            </div>


            {/* Metrics */}

            <div className="worker-metrics">

              <div className="worker-metric">

                <span>
                  Throughput
                </span>

                <strong>
                  {worker.eventsPerSecond.toLocaleString()}
                  <small>/s</small>
                </strong>

              </div>


              <div className="worker-metric">

                <span>
                  Consumer Lag
                </span>

                <strong>
                  {worker.lag}
                </strong>

              </div>

            </div>


            {/* Resource usage */}

            <div className="worker-resources">

              <div className="resource-row">

                <div className="resource-label">
                  <span>CPU</span>
                  <strong>{worker.cpu}%</strong>
                </div>

                <div className="resource-bar">
                  <div
                    className="resource-fill"
                    style={{
                      width: `${worker.cpu}%`,
                    }}
                  ></div>
                </div>

              </div>


              <div className="resource-row">

                <div className="resource-label">
                  <span>Memory</span>
                  <strong>{worker.memory}%</strong>
                </div>

                <div className="resource-bar">
                  <div
                    className="resource-fill"
                    style={{
                      width: `${worker.memory}%`,
                    }}
                  ></div>
                </div>

              </div>

            </div>


            {/* Partitions */}

            <div className="worker-partitions">

              <span>
                Partitions
              </span>

              <div className="partition-list">

                {worker.partitions.length > 0
                  ? worker.partitions.map(
                      (partition) => (
                        <span
                          key={partition}
                          className="partition-badge"
                        >
                          P
                          {String(partition).padStart(2, "0")}
                        </span>
                      )
                    )
                  : (
                    <span className="no-partitions">
                      No partitions assigned
                    </span>
                  )}

              </div>

            </div>

          </div>

        ))}

      </div>


      {/* Empty state */}

      {filteredWorkers.length === 0 && (

        <div className="workers-empty">

          <div className="empty-icon">
            ⌕
          </div>

          <h3>
            No workers found
          </h3>

          <p>
            Try changing your search or filter.
          </p>

        </div>

      )}

    </div>
  );
}


export default Workers;
